// Time Needed to Buy Tickets queue simulation
var queue = AnimatedQueue<Int>()
let k = 2
let tickets = [2, 6, 3, 4]

func timeRequiredToBuy(_ tickets: [Int], _ k: Int, q: inout AnimatedQueue<Int>) -> Int {
    for i in 0..<tickets.count {
        q.enqueue(i)
    }

    var remaining = tickets
    var time = 0

    while !q.isEmpty {
        guard let buyer = q.dequeue() else { continue }
        time += 1
        remaining[buyer] -= 1

        if buyer == k && remaining[buyer] == 0 {
            return time
        }

        if remaining[buyer] > 0 {
            q.enqueue(buyer)
        }
    }
    return time
}

let totalTime = timeRequiredToBuy(tickets, k, q: &queue)
